//! Fixture-driven crypto tests. Fixtures are generated by tools/generate_fixtures.js
//! using the vendored SJCL from the Joplin repo and node webcrypto. The Rust
//! side must decrypt every case and recover the plaintext exactly.

use joplin_rs_core::crypto as jcrypto;
use serde::Deserialize;

#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
struct Fixtures {
    sjcl: Vec<SjclCase>,
    native: Vec<NativeCase>,
    master_keys: Vec<MasterKeyCase>,
    #[serde(default)]
    sjcl_master_keys: Vec<SjclMasterKeyCase>,
    items: Vec<serde_json::Value>,
}

#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
struct SjclMasterKeyCase {
    password: String,
    key_material: String,
    encryption_method: i64,
    content: String,
}

#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
struct SjclCase {
    method: String,
    key: String,
    plain_text: String,
    cipher: String,
}

#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
struct NativeCase {
    method: String,
    key: String,
    plain_text: String,
    cipher: String,
    iterations: u32,
}

#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
struct MasterKeyCase {
    password: String,
    key_material: String,
    content: String,
}

fn load() -> Fixtures {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../fixtures/crypto_fixtures.json"
    );
    let data =
        std::fs::read_to_string(path).expect("fixtures file (run tools/generate_fixtures.js)");
    serde_json::from_str(&data).expect("parse fixtures")
}

#[test]
fn sjcl_ccm_cases() {
    let fixtures = load();
    assert!(!fixtures.sjcl.is_empty());
    for case in &fixtures.sjcl {
        let params = jcrypto::parse_sjcl(&case.cipher)
            .unwrap_or_else(|e| panic!("{}: parse: {e}", case.method));
        let result = jcrypto::sjcl_ccm_decrypt(&case.key, &params);
        match result {
            Ok(plain) => {
                let expected: String = match case.method.as_str() {
                    "SJCL1a" | "SJCL1b" => {
                        // escape()'d data: unescape first
                        let escaped =
                            String::from_utf8(plain).unwrap_or_else(|e| panic!("utf8: {e}"));
                        jcrypto::sjcl_unescape(&escaped).unwrap_or_else(|e| panic!("unescape: {e}"))
                    }
                    _ => String::from_utf8(plain).unwrap_or_else(|e| panic!("utf8: {e}")),
                };
                assert_eq!(expected, case.plain_text, "method {} case", case.method);
            }
            Err(e) => panic!("method {} case failed: {e}", case.method),
        }
    }
}

#[test]
fn native_method_cases() {
    let fixtures = load();
    for case in &fixtures.native {
        // plainText is the string Joplin's decrypt() returns (post bufferToString).
        let expected_bytes: Vec<u8> = match case.method.as_str() {
            "KeyV1" => case.plain_text.as_bytes().to_vec(),
            "FileV1" => case.plain_text.as_bytes().to_vec(),
            "StringV1" => case
                .plain_text
                .encode_utf16()
                .flat_map(|u| u.to_le_bytes())
                .collect(),
            other => panic!("unknown method {other}"),
        };
        let plain = jcrypto::native_decrypt(&case.key, &case.cipher, case.iterations)
            .unwrap_or_else(|e| panic!("{}: {e}", case.method));
        assert_eq!(plain, expected_bytes, "method {}", case.method);
    }
}

#[test]
fn master_key_cases() {
    let fixtures = load();
    for case in &fixtures.master_keys {
        let plain = jcrypto::native_decrypt(&case.password, &case.content, 220000)
            .unwrap_or_else(|e| panic!("master key: {e}"));
        let plain_str = String::from_utf8(plain).unwrap();
        assert_eq!(plain_str, case.key_material);
        assert_eq!(plain_str.len(), 512); // 256 bytes as hex
    }
}

#[test]
fn jed01_container_cases() {
    let fixtures = load();
    let mut container_count = 0;
    for item in &fixtures.items {
        let blob = match item.get("blob").and_then(|v| v.as_str()) {
            Some(b) => b,
            None => continue,
        };
        container_count += 1;
        let header = jcrypto::decode_header(blob).unwrap_or_else(|e| panic!("header: {e}"));
        assert_eq!(header.method, jcrypto::METHOD_STRING_V1);
        let master_key_id = item.get("masterKeyId").and_then(|v| v.as_str()).unwrap();
        assert_eq!(header.master_key_id, master_key_id);

        let key_material = item.get("keyMaterial").and_then(|v| v.as_str()).unwrap();
        let password = item.get("password").and_then(|v| v.as_str()).unwrap();
        let plain_text = item.get("plainText").and_then(|v| v.as_str()).unwrap();

        let header = jcrypto::decode_header(blob).unwrap_or_else(|e| panic!("header: {e}"));
        let _ = header;
        // Chunks start after the full header: 5 (JED01) + 6 (size hex) + metadata size.
        let md_size = usize::from_str_radix(&blob[5..11], 16).unwrap();
        let chunks_start = 11 + md_size;
        let chunks =
            jcrypto::decode_chunks(&blob[chunks_start..]).unwrap_or_else(|e| panic!("chunks: {e}"));
        let mut full = String::new();
        for chunk in chunks {
            let plain = jcrypto::native_decrypt(key_material, &chunk, 3)
                .unwrap_or_else(|e| panic!("chunk: {e}"));
            // StringV1 payload is utf16le
            let units: Vec<u16> = plain
                .chunks_exact(2)
                .map(|p| u16::from_le_bytes([p[0], p[1]]))
                .collect();
            full.push_str(&String::from_utf16(&units).unwrap_or_else(|e| panic!("utf16: {e}")));
        }
        assert_eq!(
            full, plain_text,
            "container roundtrip (password {password})"
        );
    }
    assert!(container_count >= 3);
}

#[test]
fn serialization_cases() {
    let fixtures = load();
    for item in &fixtures.items {
        let serialized = match item.get("serialized").and_then(|v| v.as_str()) {
            Some(s) => s,
            None => continue,
        };
        let parsed = joplin_rs_core::items::unserialize(serialized)
            .unwrap_or_else(|e| panic!("unserialize: {e}"));
        let expect = item.get("expect").unwrap();
        if let Some(title) = expect.get("title").and_then(|v| v.as_str()) {
            assert_eq!(parsed.props["title"].as_str().unwrap(), title);
        }
        if let Some(body) = expect.get("body").and_then(|v| v.as_str()) {
            assert_eq!(parsed.body, body);
        }
        if let Some(created) = expect.get("created_time_ms").and_then(|v| v.as_i64()) {
            assert_eq!(parsed.props["created_time"].as_i64().unwrap(), created);
        }
        if let Some(updated) = expect.get("updated_time_ms").and_then(|v| v.as_i64()) {
            assert_eq!(parsed.props["updated_time"].as_i64().unwrap(), updated);
        }
        if let Some(applied) = expect.get("encryption_applied").and_then(|v| v.as_i64()) {
            assert_eq!(
                parsed.props["encryption_applied"].as_i64().unwrap(),
                applied
            );
        }
    }
}

/// Real Joplin vaults commonly use SJCL (method 4) master keys rather than
/// KeyV1. The sync engine's unlock path must handle both.
#[test]
fn sjcl_master_key_unlock_cases() {
    use joplin_rs_core::storage::Storage;
    use joplin_rs_core::sync::{MasterKeyEntity, SyncEngine, SyncInfo};
    use joplin_rs_core::webdav::WebDavClient;

    let fixtures = load();
    assert!(
        !fixtures.sjcl_master_keys.is_empty(),
        "SJCL master key fixtures missing"
    );
    let storage = Storage::open_in_memory().unwrap();
    let client = WebDavClient::new("http://localhost:1/", "u", "p").unwrap();
    let engine = SyncEngine::new(&client, &storage);

    for case in &fixtures.sjcl_master_keys {
        let info = SyncInfo {
            version: 3,
            e2ee: Some(serde_json::json!({"value": true})),
            active_master_key_id: Some(serde_json::json!({"value": "mk1"})),
            master_keys: vec![MasterKeyEntity {
                id: "mk1".into(),
                created_time: 0,
                updated_time: 0,
                source_application: "test".into(),
                encryption_method: case.encryption_method,
                checksum: String::new(),
                content: case.content.clone(),
            }],
            ppk: None,
            app_min_version: None,
        };
        let key = engine
            .unlock_master_key(&info, &case.password)
            .unwrap_or_else(|e| panic!("method {}: {e}", case.encryption_method));
        assert_eq!(
            key, case.key_material,
            "method {} key material",
            case.encryption_method
        );

        // Wrong password must fail for SJCL too.
        assert!(
            engine.unlock_master_key(&info, "definitely-wrong").is_err(),
            "method {} wrong password should fail",
            case.encryption_method
        );
    }
}
